--
-- Table structure for table `transactions`
--

DROP TABLE IF EXISTS `transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transactions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `clientId` int NOT NULL,
  `type` enum('purchase','sharpening') NOT NULL,
  `description` varchar(500) NOT NULL,
  `quantity` int NOT NULL DEFAULT '1',
  `amount` decimal(12,2) NOT NULL,
  `status` enum('paid','pending','overdue') NOT NULL DEFAULT 'pending',
  `transactionDate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `notes` text DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `toolId` int DEFAULT NULL,
  `invoiceNumber` varchar(64) DEFAULT NULL,
  `cogs` decimal(12,2) NOT NULL DEFAULT '0',
  `itemId` varchar(128) DEFAULT NULL,
  `dueDate` timestamp NULL DEFAULT NULL,
  `agingBucket` enum('not_due','0_30','31_60','61_90','90_plus') DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_tx_client` (`clientId`),
  KEY `idx_tx_date` (`transactionDate`),
  KEY `idx_tx_status` (`status`),
  KEY `idx_tx_item_id` (`itemId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=30001;
/*!40101 SET character_set_client = @saved_cs_client */;

